1	package numeric
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	func writeSyntheticRecord(t *testing.T, dir string, j *storedJob) {
13		t.Helper()
14		data, err := encodeRecord(j)
15		if err != nil {
16			t.Fatal(err)
17		}
18		if err := writeFileAtomic(dir, jobFileName(j.id), data, 0o600); err != nil {
19			t.Fatal(err)
20		}
21	}
22	
23	func TestReopenPreservesTerminalRecordsAndArchive(t *testing.T) {
24		dir := t.TempDir()
25		clock := newManualClock()
26		s, err := Open(dir, WithClock(clock))
27		if err != nil {
28			t.Fatal(err)
29		}
30		started, block, release, _, _ := gateCompute(t, s)
31		block(1)
32		ok := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "ok", Values: []int64{1, 2, 3}, Seed: 4})
33		waitStarted(t, started, ok.ID)
34		cq := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "cq", Values: []int64{7}})
35		if _, err := s.Cancel(cq.ID); err != nil { // 排队中取消
36			t.Fatal(err)
37		}
38		big := int64(3037000500)
39		bad := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "bad", Values: []int64{big}})
40		release(ok.ID)
41		waitStatus(t, s, ok.ID, StatusSucceeded)
42		wantChecksum := waitStatus(t, s, ok.ID, StatusSucceeded).Archive.Checksum
43		waitStatus(t, s, bad.ID, StatusFailed)
44		if g, _ := s.Get(cq.ID); g.Status != StatusCanceled {
45			t.Fatalf("cq=%s, want canceled", g.Status)
46		}
47		if err := s.Close(); err != nil {
48			t.Fatal(err)
49		}
50	
51		s2, err := Open(dir)
52		if err != nil {
53			t.Fatal(err)
54		}
55		defer s2.Close()
56	
57		g, err := s2.Get(ok.ID)
58		if err != nil {
59			t.Fatal(err)
60		}
61		if g.Status != StatusSucceeded || g.Archive == nil {
62			t.Fatalf("success record lost: %+v", g)
63		}
64		if g.Archive.Checksum != wantChecksum || g.Archive.Sum != 6 || g.Archive.SumOfSquares != 14 {
65			t.Fatalf("archive changed across reopen: %+v", g.Archive)
66		}
67		if g.Archive.InputsDigest != inputsDigestHex([]int64{1, 2, 3}, 4) {
68			t.Fatal("inputs digest mismatch after reopen")
69		}
70		b, _ := s2.Get(bad.ID)
71		if b.Status != StatusFailed || !strings.Contains(b.FailureReason, "平方和") || b.Archive != nil {
72			t.Fatalf("failure record wrong after reopen: %+v", b)
73		}
74		c, _ := s2.Get(cq.ID)
75		if c.Status != StatusCanceled {
76			t.Fatalf("cancel record wrong after reopen: %s", c.Status)
77		}
78	
79		// 作业号续号，不复用。
80		next := mustSubmit(t, s2, SubmitRequest{Submitter: "a", Values: []int64{1}})
81		if next.ID <= cq.ID {
82			t.Fatalf("new id %d should be greater than %d", next.ID, cq.ID)
83		}
84		waitStatus(t, s2, next.ID, StatusSucceeded)
85	}
86	
87	func TestReopenIdempotencyKeySurvives(t *testing.T) {
88		dir := t.TempDir()
89		s, err := Open(dir)
90		if err != nil {
91			t.Fatal(err)
92		}
93		orig := mustSubmit(t, s, SubmitRequest{Submitter: "u", RequestID: "k1", Values: []int64{1, 2}, Seed: 3})
94		waitStatus(t, s, orig.ID, StatusSucceeded)
95		if err := s.Close(); err != nil {
96			t.Fatal(err)
97		}
98	
99		s2, err := Open(dir)
100		if err != nil {
101			t.Fatal(err)
102		}
103		defer s2.Close()
104		// 相同键相同内容 → 原作业。
105		replay, err := s2.Submit(SubmitRequest{Submitter: "u", RequestID: "k1", Values: []int64{1, 2}, Seed: 3})
106		if err != nil || replay.ID != orig.ID {
107			t.Fatalf("replay after reopen: id=%d err=%v, want %d", replayID(replay), err, orig.ID)
108		}
109		// 内容变化 → 冲突，保留原记录。
110		j, err := s2.Submit(SubmitRequest{Submitter: "u", RequestID: "k1", Values: []int64{2, 1}, Seed: 3})
111		if !errors.Is(err, ErrIdempotencyConflict) || j == nil || j.ID != orig.ID {
112			t.Fatalf("conflict after reopen: %+v %v", j, err)
113		}
114		// 不同提交人同请求号 → 新作业。
115		other := mustSubmit(t, s2, SubmitRequest{Submitter: "v", RequestID: "k1", Values: []int64{1, 2}, Seed: 3})
116		if other.ID == orig.ID {
117			t.Fatal("request id must be scoped by submitter after reopen")
118		}
119	}
120	
121	func replayID(j *Job) uint64 {
122		if j == nil {
123			return 0
124		}
125		return j.ID
126	}
127	
128	func TestReopenRecoversInterruptedRunAndBlocksDownstream(t *testing.T) {
129		// 模拟上次进程在作业 1 运行中崩溃：直接留下 running 记录，
130		// 以及一个排队等待它的作业 2、再下游作业 3。
131		dir := t.TempDir()
132		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
133		writeSyntheticRecord(t, dir, &storedJob{
134			id: 1, submitter: "a", requestID: "r1",
135			values:    []int64{1, 2},
136			queuedAt:  base,
137			startedAt: base.Add(time.Second),
138			status:    StatusRunning,
139		})
140		writeSyntheticRecord(t, dir, &storedJob{
141			id: 2, submitter: "a", requestID: "r2",
142			values: []int64{3}, dependencies: []uint64{1},
143			queuedAt: base.Add(2 * time.Second),
144			status:   StatusQueued,
145		})
146		writeSyntheticRecord(t, dir, &storedJob{
147			id: 3, submitter: "a", requestID: "r3",
148			values: []int64{4}, dependencies: []uint64{2},
149			queuedAt: base.Add(3 * time.Second),
150			status:   StatusQueued,
151		})
152	
153		s, err := Open(dir)
154		if err != nil {
155			t.Fatal(err)
156		}
157		defer s.Close()
158	
159		j1, _ := s.Get(1)
160		if j1.Status != StatusFailed || !strings.Contains(j1.FailureReason, "中断") {
161			t.Fatalf("interrupted job: status=%s reason=%q", j1.Status, j1.FailureReason)
162		}
163		if j1.Archive != nil {
164			t.Fatal("interrupted job must not carry an archive")
165		}
166		j2 := waitStatus(t, s, 2, StatusFailed)
167		j3 := waitStatus(t, s, 3, StatusFailed)
168		if j2.BlockerID != 1 || j3.BlockerID != 1 {
169			t.Fatalf("downstream blockers %d,%d want root 1", j2.BlockerID, j3.BlockerID)
170		}
171		if !strings.Contains(j2.FailureReason, "作业 1") {
172			t.Fatalf("j2 reason=%q must name blocking job 1", j2.FailureReason)
173		}
174	}
175	
176	func TestGracefulCloseInterruptsRunningJob(t *testing.T) {
177		dir := t.TempDir()
178		s, err := Open(dir)
179		if err != nil {
180			t.Fatal(err)
181		}
182		started, block, _, _, _ := gateCompute(t, s)
183		block(1)
184		j1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
185		waitStarted(t, started, j1.ID)
186	
187		// Close 会让钩子解除并使计算观察到取消；作业以“中断”失败落盘。
188		if err := s.Close(); err != nil {
189			t.Fatal(err)
190		}
191		// 重复 Close 安全。
192		if err := s.Close(); err != nil {
193			t.Fatalf("double close: %v", err)
194		}
195		// 关闭后拒绝新提交。
196		if _, err := s.Submit(SubmitRequest{Submitter: "a", Values: []int64{1}}); !errors.Is(err, ErrStoreClosed) {
197			t.Fatalf("submit after close: %v", err)
198		}
199	
200		s2, err := Open(dir)
201		if err != nil {
202			t.Fatal(err)
203		}
204		defer s2.Close()
205		g, _ := s2.Get(j1.ID)
206		if g.Status != StatusFailed || !strings.Contains(g.FailureReason, "中断") {
207			t.Fatalf("graceful close recovery: status=%s reason=%q", g.Status, g.FailureReason)
208		}
209	}
210	
211	func TestReopenResumesQueuedJobs(t *testing.T) {
212		dir := t.TempDir()
213		s, err := Open(dir)
214		if err != nil {
215			t.Fatal(err)
216		}
217		started, block, _, _, _ := gateCompute(t, s)
218		block(1)
219		j1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
220		j2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "later", Values: []int64{10, 20}})
221		waitStarted(t, started, j1.ID)
222		if err := s.Close(); err != nil {
223			t.Fatal(err)
224		}
225	
226		// 重开：j1 中断失败，j2 仍排队并继续被处理。
227		s2, err := Open(dir)
228		if err != nil {
229			t.Fatal(err)
230		}
231		defer s2.Close()
232		g1, _ := s2.Get(j1.ID)
233		if g1.Status != StatusFailed {
234			t.Fatalf("j1=%s, want failed", g1.Status)
235		}
236		done := waitStatus(t, s2, j2.ID, StatusSucceeded)
237		if done.Archive.Sum != 30 || done.Archive.SumOfSquares != 500 {
238			t.Fatalf("resumed result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
239		}
240	}
241	
242	func TestReopenFailsClosedOnCorruptedSuccessArchive(t *testing.T) {
243		dir := t.TempDir()
244		s, err := Open(dir)
245		if err != nil {
246			t.Fatal(err)
247		}
248		j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
249		waitStatus(t, s, j.ID, StatusSucceeded)
250		if err := s.Close(); err != nil {
251			t.Fatal(err)
252		}
253	
254		// 外部篡改校验值：成功状态不能继续对外宣称成功。
255		p := filepath.Join(dir, jobFileName(j.ID))
256		data, err := os.ReadFile(p)
257		if err != nil {
258			t.Fatal(err)
259		}
260		tampered := strings.Replace(string(data), `"checksum": "`, `"checksum": "f`, 1)
261		if tampered == string(data) {
262			t.Fatal("checksum field not found in record")
263		}
264		if err := os.WriteFile(p, []byte(tampered), 0o600); err != nil {
265			t.Fatal(err)
266		}
267	
268		s2, err := Open(dir)
269		if err != nil {
270			t.Fatal(err)
271		}
272		defer s2.Close()
273		g, _ := s2.Get(j.ID)
274		if g.Status != StatusFailed || g.Archive != nil {
275			t.Fatalf("corrupted archive must fail closed, got %s archive=%v", g.Status, g.Archive)
276		}
277	}
278	
279	func TestNoSuccessWithoutArchiveOnDisk(t *testing.T) {
280		// 磁盘上成功状态与归档共存于同一文件：成功作业落盘文件必须同时含两者。
281		dir := t.TempDir()
282		s, err := Open(dir)
283		if err != nil {
284			t.Fatal(err)
285		}
286		j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2, 3}})
287		waitStatus(t, s, j.ID, StatusSucceeded)
288		if err := s.Close(); err != nil {
289			t.Fatal(err)
290		}
291		data, err := os.ReadFile(filepath.Join(dir, jobFileName(j.ID)))
292		if err != nil {
293			t.Fatal(err)
294		}
295		str := string(data)
296		if !strings.Contains(str, `"status": "succeeded"`) {
297			t.Fatal("status field missing")
298		}
299		if !strings.Contains(str, `"checksum"`) || !strings.Contains(str, `"result_digest"`) ||
300			!strings.Contains(str, `"effective_values"`) || !strings.Contains(str, `"log"`) {
301			t.Fatal("succeeded record on disk must carry full archive")
302		}
303	}
